SELECT * FROM (
    SELECT a.*, ROWNUM rnum FROM (
        SELECT seller_id AS sellerId, email, representative_name AS representativeName, status, reg_date AS regDate 
        FROM seller 
        WHERE status = 'PENDING' 
        ORDER BY seller_id DESC
    ) a WHERE ROWNUM <= #{endRow}
) WHERE rnum >= #{startRow}

